"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[859],{4668:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"APP Empleo","metadata":{"permalink":"/blog-damiandevweb/blog/APP Empleo","source":"@site/blog/2024-07-28-appempleo.md","title":"Aplicacion de Empleo AMdelCo","description":"Nos complace anunciar que muy pronto lanzaremos nuestra nueva aplicaci\xf3n de empleo en AMdelCo, dise\xf1ada para revolucionar la forma en que las personas buscan y encuentran trabajo. Nuestra misi\xf3n es conectar a candidatos calificados con las mejores oportunidades laborales en el mercado.","date":"2024-07-28T00:00:00.000Z","tags":[],"readingTime":1.31,"hasTruncateMarker":true,"authors":[{"name":"Damian_Dev_Web","title":"Docente","url":"https://github.com/DamianTrajster","imageURL":"/blog-damiandevweb/img/logo-blog.png","key":"damian"}],"frontMatter":{"slug":"APP Empleo","title":"Aplicacion de Empleo AMdelCo","authors":"damian"},"unlisted":false},"content":"Nos complace anunciar que muy pronto lanzaremos nuestra nueva **aplicaci\xf3n de empleo** en AMdelCo, dise\xf1ada para revolucionar la forma en que las personas buscan y encuentran trabajo. Nuestra misi\xf3n es conectar a candidatos calificados con las mejores oportunidades laborales en el mercado.\\n\\n\\n\\n\\n\x3c!--truncate--\x3e\\n\\n## \xbfQu\xe9 Ofrece Nuestra Aplicaci\xf3n?\\n\\nLa aplicaci\xf3n de empleo de AMdelCo est\xe1 dise\xf1ada para ser intuitiva y f\xe1cil de usar, ofreciendo una experiencia fluida tanto para candidatos como para empleadores. Aqu\xed te presentamos algunas de sus caracter\xedsticas destacadas:\\n\\n![Bitumbo](/img/blog1.jpeg)\\n\\n\\n### 1. B\xfasqueda Personalizada de Empleos\\nLos usuarios pueden filtrar empleos por industria, ubicaci\xf3n, salario y otros criterios importantes. Esto permite a los solicitantes de empleo encontrar r\xe1pidamente oportunidades que se alineen con sus habilidades y preferencias.\\n\\n### 2. Perfiles de Usuario\\nCrea un perfil profesional completo con tu experiencia laboral, habilidades, educaci\xf3n y m\xe1s. Los empleadores pueden ver estos perfiles, lo que facilita la identificaci\xf3n de candidatos adecuados para sus necesidades.\\n\\n\\n### 3. Consejos y Recursos Profesionales\\nAccede a una variedad de art\xedculos, consejos y gu\xedas para mejorar tu curr\xedculum, prepararte para entrevistas y desarrollar tus habilidades profesionales.\\n\\n## \xbfC\xf3mo Empezar?\\n\\nMantente atento a nuestro lanzamiento oficial en los proximos meses.\\n\\n## Un Futuro de Oportunidades\\n\\nEn AMdelCo, creemos en el poder de la tecnolog\xeda para transformar el mercado laboral y ayudar a las personas a alcanzar su m\xe1ximo potencial. Estamos emocionados de ofrecer esta herramienta que facilitar\xe1 el proceso de b\xfasqueda de empleo y crear\xe1 nuevas oportunidades para todos.\\n\\n\xa1Gracias por ser parte de nuestra comunidad, y esperamos que encuentres el empleo perfecto con nuestra nueva aplicaci\xf3n!\\n\\n---"}]}}')}}]);